// Generated by tools/make_zones.py from the Roumen reference map. Do not edit by hand.
// zones: 1 sea, 2 sand/plaza, 3 field, 4 forest/cliff, 5 town
export const ZONE_W = 340;
export const ZONE_H = 340;
const RLE = '';
export const ZONES = (() => {
  const bin = atob(RLE);
  const out = new Uint8Array(ZONE_W * ZONE_H);
  let o = 0;
  for (let i = 0; i < bin.length; i += 2) { const v = bin.charCodeAt(i), n = bin.charCodeAt(i + 1); out.fill(v, o, o + n); o += n; }
  return out;
})();
